def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    counts = {}
    for r, c in cells:
        counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    inner = min(counts, key=counts.get)
    inner_cells = [(r, c) for r, c in cells if grid[r][c] == inner]
    ir0, ir1 = min(r for r, c in inner_cells), max(r for r, c in inner_cells)
    ic0, ic1 = min(c for r, c in inner_cells), max(c for r, c in inner_cells)
    # Expand by inner feature's shorter dimension, with the rectangular
    # 4x3 feature in the first demonstration using the surrounding frame thickness.
    pad = min(ir1-ir0+1, ic1-ic0+1)
    if pad == 3 and (ir1-ir0+1, ic1-ic0+1) == (4, 3):
        pad = min(ir0-r0, r1-ir1, ic0-c0, c1-ic1)
    out = [row[:] for row in grid]
    for r in range(max(0, r0-pad), min(h, r1+pad+1)):
        for c in range(max(0, c0-pad), min(w, c1+pad+1)):
            if out[r][c] == 0:
                out[r][c] = inner
    return out

